def apply_rule_with_shift_final(grid):
    h4_rows = [r for r in range(len(grid)) if any(grid[r][c] == 4 for c in range(len(grid[0]))) ]
    h6_rows = [r for r in range(len(grid)) if any(grid[r][c] == 6 for c in range(len(grid[0])))]

    h4_start = min(h4_rows)
    h4_end = max(h4_rows)
    h6_start = min(h6_rows)
    h6_end = max(h6_rows)

    all_shape4_rows = [list(grid[i]) for i in range(h4_start, h4_end + 1)]
    height_4_bbox = len(all_shape4_rows)
    height_6 = h6_end - h6_start + 1

    H = min(height_6, height_4_bbox)
    last_h_rows = all_shape4_rows[-H:]

    def get_col_range(rows, val):
        cols = set()
        for row in rows:
            for c, v in enumerate(row):
                if v == val:
                    cols.add(c)
        return (min(cols), max(cols)) if cols else (0, 0)

    source_cols = get_col_range(last_h_rows, 4)

    target_cols = set()
    for r in range(h6_start, h6_end + 1):
        for c, v in enumerate(grid[r]):
            if v == 6:
                target_cols.add(c)
    target_cols = (min(target_cols), max(target_cols)) if target_cols else (0, 0)

    src_center = (source_cols[0] + source_cols[1]) / 2
    tgt_center = (target_cols[0] + target_cols[1]) / 2
    shift = int(tgt_center - src_center)

    shifted_reversed = []
    for row_idx, row in enumerate(reversed(last_h_rows)):
        new_row = [0] * len(row)
        for c, val in enumerate(row):
            if val > 0:
                new_c = c + shift
                if 0 <= new_c < len(new_row):
                    new_row[new_c] = val
        shifted_reversed.append(new_row)

    result = [list(r) for r in grid]
    target_height = min(H, height_6)

    for i in range(target_height):
        dst_r = h6_start + i
        for c in range(len(result[dst_r])):
            result[dst_r][c] = shifted_reversed[i][c]

    return result

result_test = apply_rule_with_shift_final(test_in)
json_output = json.dumps({"action": "submit", "grid": result_test})
print(json_output)

